for _key, _value in _FRENCH_FORM_TEXTS.items():
    FORM_TEXTS.setdefault(_key, {})["fr"] = _value

def get_text(key, lang="ru", **kwargs):
    text = FORM_TEXTS.get(key, {}).get(
        lang,
        ADMIN_TEXTS.get(lang, ADMIN_TEXTS["en"]).get(
            key,
            BOT_UI_TEXTS.get(lang, {}).get(
                key,
                EXTRA_TEXTS.get(lang, {}).get(
                    key,
                    TEXTS.get(lang, TEXTS["ru"]).get(key, TEXTS["ru"].get(key, key)),
                ),
            ),
        ),
    )
    if kwargs:
        return text.format(**kwargs)
    return text
